var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Trailing-zero trimming must strip ALL trailing decimal zeros, not just one.
    // 1.5 KB at 4 decimal places is "1.5000" and must format as "1.5KB".
    assert.strictEqual(bytes.format(1536, { decimalPlaces: 4 }), '1.5KB');
    assert.strictEqual(bytes.format(1536, { decimalPlaces: 3 }), '1.5KB');
    assert.strictEqual(bytes.format(1024 * 1.2, { decimalPlaces: 4 }), '1.2KB');
  });
});

