describe('proof', function () {
  it('fails on the patched build', function () {
    // Without the leading ^ anchor, parse() extracts a trailing
    // number+unit from arbitrary text instead of rejecting the
    // whole string as invalid.
    assert.strictEqual(bytes('abc1kb'), null);
    assert.strictEqual(bytes('oops 10 MB'), null);
  });
});

