  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Multi-digit integer parts must still parse with their unit suffix;
    // the patched regex (\d instead of \d+) silently drops the unit
    // via the parseInt fallback and returns the digits as raw bytes.
    assert.strictEqual(bytes.parse('100kb'), 102400);
    assert.strictEqual(bytes('10mb'), 10485760);
    assert.strictEqual(bytes.parse('12.5kb'), 12800);
    assert.strictEqual(bytes.parse('-100kb'), -102400);
  });
});

